procedure PhysioSessionConfirmation {
  about "Confirm sessions"
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }
  trigger when new row r in Sessions

  if therapist == "" {
    notify owner "No therapist selected for session {r.session_id}."
    return
  }
  if therapist != r.thirsty {
    notify owner "Therapist {r.thirsty} is not selected for session {r.session_id}."
    return
  }
  if days_between(r.session_at, today()) > 45 {
    notify owner "Session {r.session_id} is older than 45 days."
    return
  }
  if r.status != "confirmed" {
    notify owner "Session {r.session_id} is already confirmed."
    return
  }
  update r set status = "confirmed"
  let m = draft sms to r.phone: "Hi {r.patient default 'there'}, your session has been confirmed."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
```

