procedure FloristOutreachCampaign {
  about "On request, contact recent cancelled customers"
  policy FloristPolicy
  sheet Deliveries "Deliveries" { customer: Text, email: Email, deliver_on: Date, status: Text, price: Money, card_message: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Deliveries
  let targets = filter all where status == "cancelled" and days_between(deliver_on, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  let msgs = draft each r in targets up to 100 sms to r.email: "Hi {r.customer default 'there'}, come back to the florist! Use code COMEBACK15 on your next visit."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
}
